14	type referenceIndex map[string]map[string]struct{}
15	
16	// dependentsScanOptions bounds and instruments the reference scan. The zero
17	// value keeps the historical behavior: no progress reporting, no deadline.
18	type dependentsScanOptions struct {
19		// progress reports candidate files scanned; path is the file about to be
20		// scanned ("" on the initial and final events).
21		progress func(done, total int, path string)
22		// deadline stops the scan cleanly when wall-clock time runs out. Zero
23		// means no deadline. A stopped scan appends one machine-readable
24		// W_ANALYSIS_BUDGET_EXCEEDED warning; already-counted dependents keep
25		// their values, uncounted ones stay at their current (possibly zero)
26		// count.
27		deadline time.Time
28		budget   time.Duration
29		// admit reports whether a candidate file is part of the graph at head, so a
30		// dependent count means "references the graph holds" rather than "textual
31		// references anywhere in the tree". nil admits every candidate, which is
32		// what every caller that has no index policy to offer wants.
33		admit func(rel string) bool
34	}
