40	func addDependentCountsWithProgress(ctx context.Context, repo, head string, result *Result, options dependentsScanOptions) error {
41		names := changedReferenceNames(*result)
42		if len(names) == 0 {
43			if options.progress != nil {
44				options.progress(0, 0, "")
45			}
46			return nil
47		}
48	
49		index, warnings, err := buildReferenceIndexWithProgress(ctx, repo, head, names, options)
50		if err != nil {
51			return err
52		}
53		result.Warnings = append(result.Warnings, warnings...)
54	
55		for fileIndex := range result.Files {
56			for changeIndex := range result.Files[fileIndex].Changes {
57				change := &result.Files[fileIndex].Changes[changeIndex]
58				name := referenceName(*change)
59				change.DependentsCount = len(index[name])
60			}
61		}
62		return nil
63	}
64	
65	func changedReferenceNames(result Result) map[string]struct{} {
66		out := map[string]struct{}{}
67		for _, file := range result.Files {
68			for _, change := range file.Changes {
69				name := referenceName(change)
70				if name != "" {
71					out[name] = struct{}{}
72				}
73			}
74		}
75		return out
76	}
