78	func buildReferenceIndex(ctx context.Context, repo, head string, names map[string]struct{}) (referenceIndex, []ProviderWarning, error) {
79		return buildReferenceIndexWithProgress(ctx, repo, head, names, dependentsScanOptions{})
80	}
81	
82	// candidateScan is one candidate file's share of the reference scan: the
83	// index entries it contributes and the warnings it raises, held until the
84	// reducer folds them in candidate order.
85	//
86	// stopped records that the worker ran out of budget. The ordered reducer also
87	// checks the deadline before accepting buffered hits, so earlier work cannot
88	// let prefetched candidates bypass the budget.
89	type candidateScan struct {
90		hits     []referenceHit
91		warnings []ProviderWarning
92		stopped  bool
93		err      error
94	}
95	
96	// referenceHit is one changed name found as an exact identifier token inside
97	// one entity. index is a set of sets, so these fold in any order; they are
98	// still applied in candidate order to keep the warnings beside them ordered.
99	type referenceHit struct {
100		token     string
101		entityKey string
102	}
103	
104	// errDependentsScanStopped unwinds the pipeline when the budget runs out. It
105	// never reaches a caller: the scan reports a stop with a warning and its
106	// partial index, exactly as the sequential scan did.
107	var errDependentsScanStopped = errors.New("dependents scan stopped")
108	
109	// dependentsScanWorkers sizes the candidate scan. It reads and parses files the
110	// same way the snapshot's parse phase does, so it takes the same bound.
111	func dependentsScanWorkers() int {
112		return defaultProviderWorkerCount()
113	}
114	
115	func buildReferenceIndexWithProgress(ctx context.Context, repo, head string, names map[string]struct{}, options dependentsScanOptions) (referenceIndex, []ProviderWarning, error) {
116		index := referenceIndex{}
117		for name := range names {
118			index[name] = map[string]struct{}{}
119		}
120		if len(names) == 0 {
121			return index, nil, nil
122		}
123	
124		overBudget := func() bool {
125			return !options.deadline.IsZero() && !time.Now().Before(options.deadline)
126		}
127		if overBudget() {
128			return index, []ProviderWarning{dependentsBudgetWarning(0, -1, options.budget)}, nil
129		}
130	
131		files, prefiltered, warnings, err := referenceCandidateFiles(ctx, repo, head, names)
132		if err != nil {
133			return nil, nil, err
134		}
135		// Drop candidates the graph does not index before any of them is read. A
136		// caller inside a vendored or .graphignore'd tree is not a dependent the
137		// graph can show: after the diff stopped naming those files, counting them
138		// left a number nothing in the output accounted for.
139		if options.admit != nil {
140			admitted := files[:0]
141			for _, file := range files {
142				if options.admit(file) {
143					admitted = append(admitted, file)
144				}
145			}
146			files = admitted
147		}
148		if options.progress != nil {
149			options.progress(0, len(files), "")
150		}
151	
152		// One persistent `git cat-file --batch-command` process replaces a one-shot Git
153		// subprocess per candidate file; on large repos the per-file spawn cost
154		// alone was tens of seconds. Paths the LF protocol cannot represent and a
155		// batch startup failure share one bounded metadata reader, so exceptional
156		// deep paths cannot each reset the component-process allowance.
157		limited := gitutil.NewLimitedFileReader(ctx, repo, head, defaultMaxParseBytes)
158		limited.SetDeadline(options.deadline)
159		defer func() { _ = limited.Close() }()
160	
161		// The candidate scan below runs on workers, so everything a read records for
162		// the warnings that follow it is behind one lock. Each entry is written once
163		// per candidate and read once, so the lock is never contended for long.
164		var readOutcomeMu sync.Mutex
165		limitedOversize := map[string]int64{}
166		// limitedOversizeUnscanned records every oversized path whose size came
167		// from LimitedFileReader rather than the batch reader's oversize scanner
168		// below: LimitedFileReader has no content-scanning capability of its own,
169		// so oversizeMatched can never be populated for these paths. That used to
170		// silently read as "did not match" on the full-tree fallback (prefiltered
171		// == false), undercounting dependents for any line-unsafe or
172		// batch-ineligible oversized file that does contain a changed name. With
173		// no candidate evidence either way, warn rather than assume a miss.
174		limitedOversizeUnscanned := map[string]bool{}
175		limitedUnaddressable := map[string]bool{}
176		limitedUnavailable := map[string]gitutil.LimitedFileStatus{}
177		readLimitedFile := func(path string) (string, bool, error) {
178			if !gitutil.IsCanonicalGitTreePath(path) {
179				readOutcomeMu.Lock()
180				limitedUnaddressable[path] = true
181				readOutcomeMu.Unlock()
182				return "", false, nil
183			}
184			result, err := limited.ReadFile(path)
185			if err != nil {
186				return "", false, err
187			}
188			// Every outcome a read records goes under the one lock, in one
189			// acquisition. The statuses are distinct values, so folding the three
190			// separate checks into one switch records exactly what they did.
191			readOutcomeMu.Lock()
192			switch result.Status {
193			case gitutil.LimitedFileOversize:
194				limitedOversize[path] = result.Bytes
195				limitedOversizeUnscanned[path] = true
196			case gitutil.LimitedFileUnaddressable:
197				limitedUnaddressable[path] = true
198			case gitutil.LimitedFileMissing, gitutil.LimitedFileNonBlob, gitutil.LimitedFileUnreadable:
199				limitedUnavailable[path] = result.Status
200			}
201			readOutcomeMu.Unlock()
202			return result.Content, result.Status == gitutil.LimitedFileContent, nil
203		}
204		readFile := readLimitedFile
205		// oversizeBytes reports a file the reader declined because it exceeds the
206		// parse limit, so the scan can warn about it (below) without the read that
207		// would have cost the file's size twice for a file it refuses to parse anyway.
208		// Set for an oversized blob whose streamed bytes contained a changed name.
209		oversizeMatched := map[string]bool{}
210		oversizeBytes := func(path string) (int64, bool) {
211			readOutcomeMu.Lock()
212			defer readOutcomeMu.Unlock()
213			size, ok := limitedOversize[path]
214			return size, ok
215		}
216		batch, batchErr := gitutil.NewBatchFileReader(ctx, repo, head)
217		if batchErr == nil {
218			defer func() { _ = batch.Close() }()
219			batch.SetMaxBytes(defaultMaxParseBytes)
220			readFile = func(path string) (string, bool, error) {
221				if !gitutil.IsCanonicalGitTreePath(path) || !batch.IsPathSafe(path) {
222					return readLimitedFile(path)
223				}
224				content, ok, err := batch.ReadFile(path)
225				if err == nil && !ok {
226					if _, oversize := batch.OversizeBlob(path); !oversize {
227						// Git grep already proved a prefiltered path existed and
228						// matched. A later missing/non-blob batch response means the
229						// promised blob became unavailable between discovery and read.
230						readOutcomeMu.Lock()
231						limitedUnavailable[path] = gitutil.LimitedFileUnreadable
232						readOutcomeMu.Unlock()
233					}
234				}
235				return content, ok, err
236			}
237			oversizeBytes = func(path string) (int64, bool) {
238				readOutcomeMu.Lock()
239				size, ok := limitedOversize[path]
240				readOutcomeMu.Unlock()
241				if ok {
242					return size, true
243				}
244				blob, ok := batch.OversizeBlob(path)
245				return blob.Bytes, ok
246			}
247			// An oversized blob is streamed past and discarded, so its content is never available to
248			// isCandidate below. Decide relevance during that same pass: if none of the changed names
249			// appears in the blob, it was never a candidate and must not produce a warning (the fallback
250			// scan would otherwise spray E_FILE_TOO_LARGE over every huge vendored blob in the tree).
251			// Chunks may split an identifier, so carry maxNameLen-1 bytes of overlap between them.
252			maxNameLen := 0
253			for name := range names {
254				if len(name) > maxNameLen {
255					maxNameLen = len(name)
256				}
257			}
258			carry := map[string]string{}
259			batch.SetOversizeScanner(func(path string, chunk []byte) {
260				readOutcomeMu.Lock()
261				defer readOutcomeMu.Unlock()
262				if oversizeMatched[path] {
263					return
264				}
265				window := carry[path] + string(chunk)
266				if containsAnyName(window, names) {
267					oversizeMatched[path] = true
268					delete(carry, path)
269					return
270				}
271				if keep := maxNameLen - 1; keep > 0 && len(window) > keep {
272					window = window[len(window)-keep:]
273				}
274				carry[path] = window
275			})
276		}
277	
278		// Prime exactly the canonical, supported paths that will use the fallback,
279		// in candidate-list order. Without this pass, every LF-unsafe short path
280		// performs its own lazy ls-tree lookup even though LimitedFileReader can
281		// resolve up to 128 exact paths per bounded metadata subprocess. If the
282		// primary content batch failed to start, every readable candidate uses the
283		// same primed fallback instead.
284		limitedPaths := make([]string, 0, len(files))
285		for _, path := range files {
286			if !Supported(path) || !gitutil.IsCanonicalGitTreePath(path) {
287				continue
288			}
289			if batchErr != nil || !batch.IsPathSafe(path) {
290				limitedPaths = append(limitedPaths, path)
291			}
292		}
293		if err := limited.Prime(limitedPaths); err != nil {
294			return nil, nil, err
295		}
296		// A bounded metadata batch can consume the remaining analysis budget. Keep
297		// the existing semantics: stop before parsing and report one budget warning,
298		// rather than misclassifying deadline-driven component results as read errors.
299		if len(files) > 0 && overBudget() {
300			warnings = append(warnings, dependentsBudgetWarning(0, len(files), options.budget))

