func configuresRelations(recordsByFile map[string][]SymbolRecord, readContent contentReader) []RelationRecord {
	paths := make([]string, 0, len(recordsByFile))
	for path := range recordsByFile {
		paths = append(paths, path)
	}
	sort.Strings(paths)

