					Type:          "CONFIGURES",
					Confidence:    cfg.Confidence,
					Reason:        cfg.Reason,
					RelationScope: "external",
					Resolution:    "pattern",
					TargetKind:    "config",
					Evidence: []Evidence{{
						Kind:      cfg.EvidenceKind,
						FilePath:  symbol.FilePath,
						StartLine: symbol.StartLine,
						EndLine:   symbol.EndLine,
